          gBattle_BG3_Y = 0;
          if (mode == INFOCARD_MATCH)
              gBattle_BG2_X = 0, gBattle_BG2_Y = 0;
          else
              gBattle_BG2_X = 0, gBattle_BG2_Y = DISPLAY_HEIGHT;

          task.data[0]++;
